mapper.select:
SELECT
tc.*,
sc.consumable_name AS consumable_name,
su.user_name AS manager_name,
pt.name AS toilet_name,
sa.area_name AS area_name
FROM public_toilet_consumable tc
-- 1. 关联耗材表（核心表）
LEFT JOIN sys_consumable sc ON tc.consumable_id = sc.consumable_id AND sc.deleted = 0
-- 2. 关联公厕表（耗材表关联公厕表，获取 areacode）
LEFT JOIN public_toilet pt ON tc.toilet_id = pt.toilet_id AND pt.deleted = 0
-- 3. 新增：关联区域编码表（通过公厕表的 areacode 获取区域名称）
LEFT JOIN sys_area sa ON pt.area_code = sa.area_code AND sa.deleted = 0
-- 4. 关联负责人表
LEFT JOIN sys_user su ON tc.manager_id = su.user_id AND su.deleted = 0
WHERE tc.deleted = 0



    AND tc.toilet_id = #{reqVO.toiletId}


    AND tc.consumable_id = #{reqVO.consumableId}


    AND tc.consumable_stock BETWEEN #{reqVO.consumableStock[0]} AND #{reqVO.consumableStock[1]}


    AND tc.consumable_threshold BETWEEN #{reqVO.consumableThreshold[0]} AND #{reqVO.consumableThreshold[1]}


    AND tc.consumable_warning = #{reqVO.consumableWarning}


    AND tc.last_supply_time BETWEEN #{reqVO.lastSupplyTime[0]} AND #{reqVO.lastSupplyTime[1]}


    AND tc.supply_cycle BETWEEN #{reqVO.supplyCycle[0]} AND #{reqVO.supplyCycle[1]}


    AND tc.consumable_gap BETWEEN #{reqVO.consumableGap[0]} AND #{reqVO.consumableGap[1]}


    AND tc.manager_id = #{reqVO.managerId}


ORDER BY tc.id DESC
LIMIT #{reqVO.offset}, #{reqVO.limit}

SELECT COUNT(DISTINCT tc.id)
FROM public_toilet_consumable tc
LEFT JOIN sys_consumable sc ON tc.consumable_id = sc.consumable_id AND sc.deleted = 0
LEFT JOIN public_toilet pt ON tc.toilet_id = pt.toilet_id AND pt.deleted = 0
LEFT JOIN sys_area sa ON pt.area_code = sa.area_code AND sa.deleted = 0
LEFT JOIN sys_user su ON tc.manager_id = su.user_id AND su.deleted = 0
WHERE tc.deleted = 0



